[CmdletBinding()]
param([switch]$Execute,[string]$ApprovalPhrase,[string]$BackupRoot='C:\VAMBAM\Projects\OTG\DEV\production_backups',[switch]$Simulation,[string]$SimulationRoot='C:\VAMBAM\Projects\OTG\DEV\production_tooling_sandbox_107',[int]$SimulationPort=18502)
$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'production_update_common.ps1'); if($Simulation){Assert-Simulation $SimulationRoot $SimulationPort; if(-not $Execute){'MODE=DRY_RUN';'SIMULATION=YES';'MUTATION_EXECUTED=NO';exit 0}; Assert-Approval $Execute $ApprovalPhrase 'BACKUP_OTG_ANALYTICS_8502'; $b=Join-Path $SimulationRoot 'backups\simulated'; New-Item -ItemType Directory -Path $b -Force|Out-Null; Copy-Item (Join-Path $SimulationRoot 'production\.env') (Join-Path $b '.env'); Copy-Item (Join-Path $SimulationRoot 'production\production.db') (Join-Path $b 'production.dump'); $m=[ordered]@{manifest_version=2;created_at=(Get-Date).ToUniversalTime().ToString('o');target_root=$SimulationRoot;target_port=$SimulationPort;target_app=$ExpectedApp;old_git_head='old';old_git_branch='main';old_git_clean=$true;env_backup_relative_path='.env';env_sha256=Get-Sha256 (Join-Path $b '.env');git_bundle_relative_path='production.bundle';git_bundle_sha256='simulation';db_dump_relative_path='production.dump';db_dump_sha256=Get-Sha256 (Join-Path $b 'production.dump');db_dump_format='custom';db_dump_validation='PASS';dynamic_artifacts=@();active_runtime_existed=$false;production_refresh_tasks=@();backup_complete=$true}; $m|ConvertTo-Json -Depth 8|Set-Content (Join-Path $b 'BACKUP_MANIFEST.json'); 'MODE=EXECUTE'; 'SIMULATION=YES'; "BACKUP_MANIFEST_PATH=$(Join-Path $b 'BACKUP_MANIFEST.json')";'MUTATION_EXECUTED=YES';exit 0}; Assert-ProductionTarget; Assert-Approval $Execute $ApprovalPhrase 'BACKUP_OTG_ANALYTICS_8502'
$tools=Get-PostgresTools; $envPath=Join-Path $ExpectedRoot '.env'; $p=Get-8502Process; $head=(git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot rev-parse HEAD); $branch=(git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot branch --show-current); $clean=[string]::IsNullOrEmpty((git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot status --porcelain))
"MODE=$(if($Execute){'EXECUTE'}else{'DRY_RUN'})"; "TARGET_ROOT=$ExpectedRoot"; "TARGET_PORT=$ExpectedPort"; "GIT_HEAD=$head"; "GIT_CLEAN=$(if($clean){'YES'}else{'NO'})"; "PG_DUMP_AVAILABLE=$(if($tools.ContainsKey('pg_dump')){'YES'}else{'NO'})"; "PG_RESTORE_AVAILABLE=$(if($tools.ContainsKey('pg_restore')){'YES'}else{'NO'})"; "PSQL_AVAILABLE=$(if($tools.ContainsKey('psql')){'YES'}else{'NO'})"; "BACKUP_SET_VALID=$(if($tools.Count -eq 3 -and (Test-Path $envPath)){'YES'}else{'NO'})"
if($tools.Count -ne 3 -or -not(Test-Path $envPath)){throw 'BACKUP_TOOL_OR_ENV_UNAVAILABLE'}
Invoke-GuardedAction -Execute:$Execute -Name 'CREATE_BACKUP_MANIFEST_AND_DATABASE_DUMP' -Action { $stamp=Get-Date -Format yyyyMMdd_HHmmss; $out=Join-Path $BackupRoot $stamp; New-Item -ItemType Directory -Path $out -Force|Out-Null; git -c "safe.directory=$ExpectedRoot" -C $ExpectedRoot bundle create (Join-Path $out 'production.bundle') HEAD; Copy-Item $envPath (Join-Path $out '.env'); $manifest=[ordered]@{manifest_version=1;created_at=(Get-Date).ToUniversalTime().ToString('o');target_root=$ExpectedRoot;target_port=$ExpectedPort;target_app=$ExpectedApp;old_git_head=$head;old_git_branch=$branch;old_git_clean=$clean;env_backup_relative_path='.env';env_sha256=(Get-Sha256 (Join-Path $out '.env'));db_dump_relative_path='production.dump';db_dump_format='custom';backup_complete=$false}; $safe=Get-SafeEnv $envPath; $oldPwd=$env:PGPASSWORD; try{$env:PGHOST=$safe.POSTGRES_HOST;$env:PGPORT=$safe.POSTGRES_PORT;$env:PGUSER=$safe.POSTGRES_USER;$env:PGPASSWORD=$safe.POSTGRES_PASSWORD;$env:PGDATABASE=$safe.POSTGRES_DB;& $tools.pg_dump '--format=custom' '--file' (Join-Path $out 'production.dump'); if($LASTEXITCODE -ne 0){throw 'PG_DUMP_FAILED'}; & $tools.pg_restore '--list' (Join-Path $out 'production.dump'); if($LASTEXITCODE -ne 0){throw 'PG_RESTORE_LIST_FAILED'};$manifest.db_dump_sha256=Get-Sha256 (Join-Path $out 'production.dump');$manifest.db_dump_validation='PASS';$manifest.backup_complete=$true}finally{$env:PGPASSWORD=$oldPwd}; $manifest|ConvertTo-Json -Depth 8|Set-Content (Join-Path $out 'BACKUP_MANIFEST.json') -Encoding UTF8; "BACKUP_MANIFEST_PATH=$(Join-Path $out 'BACKUP_MANIFEST.json')" }
"MUTATION_EXECUTED=$(if($Execute){'YES'}else{'NO'})"
